OPTION_TEXT_OVERRIDES = {
    "module2-5-v1-20261006": {
        "M2L5-010": {2: "append adds w as one item; extend removes its items from the list"},
        "M2L5-013": {1: "The last item whose value equals 20"},
        "M2L5-037": {1: "Each income's original row position determines its rank"},
    }
}


def apply_option_feedback(bank_name, items):
    """Attach complete, option-ordered rationales to items with reviewed entries."""
    updates = OPTION_FEEDBACK.get(bank_name, {})
    text_updates = OPTION_TEXT_OVERRIDES.get(bank_name, {})
    seen = set()
    for item in items:
        item_id = item.get("id")
        for option_index, option_text in text_updates.get(item_id, {}).items():
            item["options"][option_index] = option_text
        if item_id not in updates:
            continue
        reasons = updates[item_id]
        options = item.get("options", [])
        key = item.get("correctIndex")
        if len(reasons) != len(options) or key is None or not 0 <= key < len(options):
            raise ValueError(f"Invalid option-feedback alignment for {item_id}")
        if reasons[key] is not None:
            raise ValueError(f"Correct option must reuse the reviewed explanation for {item_id}")
        item["optionExplanations"] = [item.get("explanation") if reason is None else reason for reason in reasons]
        seen.add(item_id)
    missing = set(updates) - seen
    if missing:
        raise ValueError(f"Option-feedback items missing from {bank_name}: {sorted(missing)}")
    return items
